/**
 * Client-side message & attachment encryption.
 *
 * Every conversation has a random AES-256-GCM key (generated by its
 * creator, stored in the members-only `chat_keys` row). Message text
 * is encrypted in the browser before insert; attachments are
 * encrypted before upload to the private `chat-files` bucket. The
 * database and object storage only ever hold ciphertext.
 *
 * All primitives come from the Web Crypto API — no dependencies.
 */

const SUBTLE = globalThis.crypto.subtle;

export interface EncryptedPayload {
  cipherB64: string;
  iv: string;
}

function toBase64(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

function fromBase64(value: string): Uint8Array {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index++) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

/** Generates a fresh conversation key, base64-encoded (raw 32 bytes). */
export function generateConversationKey(): string {
  const bytes = new Uint8Array(32);
  globalThis.crypto.getRandomValues(bytes);
  return toBase64(bytes);
}

async function importKey(keyB64: string): Promise<CryptoKey> {
  if (!SUBTLE) throw new Error("Encryption is unavailable in this browser");
  return SUBTLE.importKey("raw", fromBase64(keyB64).buffer as ArrayBuffer, "AES-GCM", false, [
    "encrypt",
    "decrypt",
  ]);
}

/** Encrypts a UTF-8 string with the conversation key. */
export async function encryptText(keyB64: string, plaintext: string): Promise<EncryptedPayload> {
  const key = await importKey(keyB64);
  const iv = new Uint8Array(12);
  globalThis.crypto.getRandomValues(iv);
  const encoded = new TextEncoder().encode(plaintext);
  const cipher = await SUBTLE.encrypt(
    { name: "AES-GCM", iv: iv.buffer as ArrayBuffer },
    key,
    encoded.buffer as ArrayBuffer,
  );
  return { cipherB64: toBase64(new Uint8Array(cipher)), iv: toBase64(iv) };
}

/** Decrypts a message body. Returns null for undecryptable content. */
export async function decryptText(
  keyB64: string,
  cipherB64: string,
  iv: string,
): Promise<string | null> {
  if (!cipherB64 || !iv) return "";
  try {
    const key = await importKey(keyB64);
    const plain = await SUBTLE.decrypt(
      { name: "AES-GCM", iv: fromBase64(iv).buffer as ArrayBuffer },
      key,
      fromBase64(cipherB64).buffer as ArrayBuffer,
    );
    return new TextDecoder().decode(plain);
  } catch {
    // Wrong key (member added before key rotation) or corrupt row.
    return null;
  }
}

/**
 * Encrypts a file for upload. Returns the encrypted blob plus the
 * random IV, which callers persist alongside the message metadata.
 * Format of the uploaded bytes: [12-byte IV][ciphertext].
 */
export async function encryptFile(keyB64: string, file: Blob): Promise<{ blob: Blob; iv: string }> {
  const key = await importKey(keyB64);
  const iv = new Uint8Array(12);
  globalThis.crypto.getRandomValues(iv);
  const buffer = await file.arrayBuffer();
  const cipher = await SUBTLE.encrypt(
    { name: "AES-GCM", iv: iv.buffer as ArrayBuffer },
    key,
    buffer,
  );
  const ivAndCipher = new Uint8Array(12 + cipher.byteLength);
  ivAndCipher.set(iv, 0);
  ivAndCipher.set(new Uint8Array(cipher), 12);
  return { blob: new Blob([ivAndCipher], { type: "application/octet-stream" }), iv: toBase64(iv) };
}

/** Decrypts a downloaded attachment back into its original form. */
export async function decryptFile(keyB64: string, data: ArrayBuffer): Promise<Blob> {
  const key = await importKey(keyB64);
  const iv = new Uint8Array(data.slice(0, 12));
  const cipher = data.slice(12);
  const plain = await SUBTLE.decrypt(
    { name: "AES-GCM", iv: iv.buffer as ArrayBuffer },
    key,
    cipher,
  );
  return new Blob([plain]);
}

export { toBase64, fromBase64 };
